const concepts=[
 {id:'zelda',name:'Zelda · Breath of the Wild',tag:'ATLAS / SHEIKAH',color:'#bdad72',description:'Um atlas de exploração: terra gravada, bordas delicadas e sinais luminosos sobre uma cartografia de aparência antiga.',features:[['Vias','Traços finos e caminhos pontilhados; hierarquia sem avenidas grossas.'],['Terreno','Bordas sucessivas dos parques e lagos como gravura. Altimetria real seria uma etapa própria.'],['Ícones & letras','Marcas geométricas ciano, selos de localização e lettering serifado discreto.']],why:'Mistura material antigo e tecnologia, com espaço para um relevo real no futuro.',source:'https://zelda.nintendo.com/features/',sourceLabel:'Referência: Sheikah Slate · Nintendo'},
 {id:'fallout',name:'Fallout · Pip-Boy',tag:'PHOSPHOR / LOCAL MAP',color:'#73dc8d',description:'Uma tela de terminal portátil. A cidade vira um conjunto de linhas de fósforo, símbolos funcionais e vazios bem definidos.',features:[['Vias','Rede vetorial com brilho contido e espessuras por importância.'],['Terreno','Prédios em contorno, água por retícula e linhas de varredura muito discretas.'],['Ícones & letras','Pictogramas monocromáticos com silhueta própria; letras de terminal.']],why:'É o mais distante das paletas atuais: muda a forma de representar cada objeto.',source:'https://help.bethesda.net/app/answers/detail/a_id/31464/~/what-can-the-fallout-4-pip-boy-app-do%3F',sourceLabel:'Referência: Pip-Boy · Bethesda'},
 {id:'animal',name:'Animal Crossing',tag:'MINIATURE / NEIGHBORHOOD',color:'#97b983',description:'Uma pequena vila para passear: ruas de areia, construções como miniaturas e parques com aspecto de jardim.',features:[['Vias','Caminhos macios, bordas arredondadas e entroncamentos limpos.'],['Terreno','Coberturas em camadas, sombra deslocada e margens de lago com faixa clara.'],['Ícones & letras','Casinha, comércio e árvores como objetos de brinquedo; tipografia redonda.']],why:'Uma alternativa acolhedora e natural, com identidade diferente do doce e rosa do Pink World.',source:'https://animalcrossing.nintendo.com/new-horizons/explore/',sourceLabel:'Referência: vida na ilha · Nintendo'},
 {id:'hollow',name:'Hollow Knight',tag:'INK / NOCTURNE',color:'#b0bdd1',description:'Um caderno de cartógrafo à noite: tinta clara, áreas de penumbra e detalhes desenhados à mão em um mapa silencioso.',features:[['Vias','Linhas de tinta com borda suave, mantendo a rede real de ruas.'],['Terreno','Construções hachuradas, lagos fundos e ornamentos nas margens do painel.'],['Ícones & letras','Bancos, lanternas e pequenas fachadas; letras delicadas com alto contraste.']],why:'Traz uma estética noturna orgânica, sem depender de neon ou circuitos.',source:'https://www.hollowknight.com/',sourceLabel:'Referência: arte desenhada à mão · Team Cherry'},
 {id:'sea',name:'Sea of Thieves',tag:'CHART / EXPLORATION',color:'#bf9a5e',description:'Uma carta de navegação desenhada sobre papel: grade, rosa dos ventos, lagos gravados e marcos em tinta.',features:[['Vias','Traços finos de pena, caminhos descontínuos e poucos símbolos de orientação.'],['Terreno','Hachuras dos prédios, bordas aquareladas e textura de papel envelhecido.'],['Ícones & letras','Marcos desenhados como carimbos, bússolas e lettering de cartógrafo.']],why:'Transforma a leitura da cidade em exploração náutica sem transformar Goiânia em um oceano.',source:'https://www.seaofthieves.com/',sourceLabel:'Universo de referência: Rare / Sea of Thieves'}
];
document.getElementById('concepts').innerHTML=concepts.map((c,i)=>`<article class="concept" style="--accent:${c.color}"><button class="artwork" data-preview="${c.id}" aria-label="Ampliar proposta ${c.name}"><img src="./proposals/${c.id}.svg" alt="Estudo vetorial ${c.name} sobre o recorte real do Bosque dos Buritis"><span class="image-label"><b>0${i+1}</b>${c.tag}</span><span class="expand">Ampliar ↗</span></button><div class="concept-body"><span class="eyebrow">PROPOSTA 0${i+1}</span><h2>${c.name}</h2><p class="description">${c.description}</p><dl>${c.features.map(([name,text])=>`<div><dt>${name}</dt><dd>${text}</dd></div>`).join('')}</dl><p class="why">${c.why}</p><a class="source" href="${c.source}" target="_blank" rel="noopener">${c.sourceLabel} ↗</a></div></article>`).join('');
const dialog=document.getElementById('preview-dialog');
document.querySelectorAll('[data-preview]').forEach(button=>button.onclick=()=>{const c=concepts.find(c=>c.id===button.dataset.preview);document.getElementById('large-preview').src='./proposals/'+c.id+'.svg';document.getElementById('large-preview').alt=c.name+' — estudo cartográfico';document.getElementById('large-title').textContent=c.name;dialog.showModal();});
document.getElementById('close-preview').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
